from pathlib import Path
import shutil
B=Path(__file__).resolve().parents[2]
p=B/'app/dist/economy-ledger.js';s=p.read_text(encoding='utf-8')
s="import {forcedLaborPeople} from './economy-labor.js?v=42';\n"+s
s=s.replace('${incomeHTML(r.cities)}','${laborHTML(c,r.cities)}${incomeHTML(r.cities)}')
marker=' function incomeHTML(cities)'
block=''' function laborHTML(c,cities){const initial=cities.reduce((n,b)=>n+forcedLaborPeople(b),0);if(!initial)return '';const ids=new Set(cities.map(b=>'city:'+b.i)),installed=cities.reduce((n,b)=>n+(c.state.accounts['city:'+b.i]?.assets[31]||0),0),stock=cities.reduce((n,b)=>n+(c.state.accounts['city:'+b.i]?.stock[31]||0),0),trades=c.state.last.trades.filter(t=>t.good===31&&(ids.has(t.from)||ids.has(t.to)));return `<details class="ledgerLabor"><summary>⛓ Trabalho escravizado e comércio</summary><p>Regime de trabalho e estoque de pessoas existentes, incluídas no censo inicial. Não há salário atribuído às pessoas escravizadas; sua alimentação participa da demanda local. A apropriação de trabalho afeta os custos operacionais de referência, sem bônus automático de produção.</p>${metrics([[num(initial),'Pessoas no censo inicial · estimativa'],[num(installed),'Trabalho alocado na simulação'],[num(stock),'Estoque disponível para transferência']])}<p>${num(trades.reduce((n,t)=>n+t.units,0))} pessoas transferidas neste recorte. O percentual inicial é editável na cidade. Alterá-lo afeta uma nova simulação; ciclos já salvos conservam seus estoques.</p><button data-ledger-kind="good" data-ledger-id="31">Ver estoques e comércio de pessoas escravizadas</button></details>`;}
 function captiveHTML(c,g){const cities=D.cities.filter(b=>forcedLaborPeople(b)>0),trades=c.state.last.trades.filter(t=>t.good===31),held=cities.reduce((n,b)=>n+(c.state.accounts['city:'+b.i]?.assets[31]||0),0),available=cities.reduce((n,b)=>n+(c.state.accounts['city:'+b.i]?.stock[31]||0),0);return `<button data-ledger-kind="goods" data-ledger-id="0">← Todos os produtos</button><h2>⛓ Pessoas escravizadas</h2><p>Comércio de estoques finitos em Drácon, Husaj e Território Orc. Pessoas não são produzidas por ciclo nem consumidas como equipamento. Transferências respeitam rotas, guerras, embargos, fretes e tarifas.</p>${metrics([[num(held),'Trabalho alocado'],[num(available),'Estoque para transferência'],[num(trades.reduce((n,t)=>n+t.units,0)),'Pessoas transferidas no recorte']])}<p>Censo inicial estimado: 12% em Drácon, 15% em Husaj e 8% no Território Orc, fora das escolas de magia; são hipóteses editáveis. Não há captura ou reprodução automática. O censo urbano aprovado não é atualizado automaticamente por essas transferências.</p><h3>Localidades e estoques</h3>${cities.map(b=>nav('city',b.i,title(b),`${sn(b.state)} · ${num(c.state.accounts['city:'+b.i]?.assets[31]||0)} alocadas · ${num(c.state.accounts['city:'+b.i]?.stock[31]||0)} disponíveis`,'⛓')).join('')}<p>Capturas por piratas registradas: ${num(c.state.accounts['captivity:0']?.assets[31]||0)}. Essas pessoas continuam contabilizadas.</p><h3>Preços e ofertas</h3>${marketPrices(c,g)}<h3>Transações no recorte</h3>${trades.map(t=>`<p>${esc(an(t.from))} → ${esc(an(t.to))}: ${num(t.units)} pessoas · ${money(t.coins/100)}</p>`).join('')||'<p>Sem transferências neste recorte.</p>'}`;}
'''
assert marker in s;s=s.replace(marker,block+marker)
s=s.replace('good=g.i;\n  return',"good=g.i;if(g.i===31)return captiveHTML(c,g);\n  return")
s=s.replace('Object.entries(c.state.last.production)){if(!(rows[g.i]>0))continue;',"Object.entries(g.i===31?Object.fromEntries(Object.entries(c.state.accounts).map(([id,a])=>[id,a.stock])):c.state.last.production)){if(!(rows[g.i]>0))continue;")
s=s.replace('Cotação indicativa por unidade produzida, sem reservar estoque ou caixa.', 'Cotação indicativa por unidade comercial, sem reservar estoque ou caixa.')
s=s.replace("${g.kind==='manufacture'?'Manufaturado':'Recurso / extração'}", "${g.i===31?'Estoque finito · comércio':g.kind==='manufacture'?'Manufaturado':'Recurso / extração'}")
p.write_text(s,encoding='utf-8')
p=B/'app/dist/economy-ui.js';s=p.read_text(encoding='utf-8').replace('[...model.goods.values()].sort','[...model.goods.values()].filter(g=>!g.inactive).sort');s=s.replace('conforme o ajuste por habitante','conforme a liquidez familiar inicial configurada');p.write_text(s,encoding='utf-8')
for p in (B/'app/dist').glob('*.js'):shutil.copy2(p,B.parent/'silvengard-atlas v2/dist'/p.name)
shutil.copy2(B/'market_defaults.py',B.parent/'silvengard-atlas v2/market_defaults.py')
